"""Initial source-only claims/findings for Rust ooutwire scope."""
import json,pathlib
H=pathlib.Path(__file__).resolve().parent;P='additional_rust_ooutwire_remaining';fs=json.loads((H/(P+'_scope.json')).read_text())['files'];p=H/(P+'.json');r=json.loads(p.read_text())
def e(i,a,b):return {'path':fs[i]['path'],'sha256':fs[i]['sha256'],'lines':[a,b]}
c={'id':'ROUT-C001','claim':'The finite core admits a declared five-field regime and six-event grammar: Supply is value-inert, token re-admission designates, forms have positive arity, instances reference admitted forms/marks, and impositions add ordered persistent pairs. Replay is a Result-valued deterministic fold; certification checks exact presented-state equality with that replay.','evidence':[e(54,51,114),e(34,18,34),e(1,25,78),e(38,22,31),e(57,24,37),e(29,20,27)],'dependencies':['Valid admitted base regime; successful finite memory operations','Designation, positive arity and external imposition are chosen semantics','Existing compiler/runtime semantics, not executed in this review'],'limitations':['These are source-defined objects, not a derivation from primitive cut or a unique foundational model','Replay determinism/append law follows by induction on the declared fold; existing test source is separate finite evidence and was not run','Certification does not establish authenticity, task truth, canonical equivalence or exhaustive search']}
f={'id':'ROUT-F001','severity':'high','title':'GateReceipt unit test has ownership and trait requirements unsatisfied by its types','finding':'lib.rs:287 maps a receipt to(receipt.fuel_after(),receipt.licensed()); both accessors consume self and GateReceipt is not Copy. The second access uses a moved value. assert_eq! on Result additionally requires GateError PartialEq and Debug, neither derived nor implemented in the scoped source. This is a source-established test-compilation obstruction, not an observed compiler run.','evidence':[e(40,242,277),e(40,280,296)],'recommended_action':'Borrow receipt in read-only accessors or destructure it once, and compare error variants by matches or provide suitable traits. Run the actual test target after a separately authorized repair.','validation':'Entire lib.rs read plus rg of GateError/GateReceipt definitions and impls in scoped src; no native or Cargo execution.'}
for field,items in [('claims',[c]),('findings',[f])]:
 d={x['id']:x for x in r[field]};d.update({x['id']:x for x in items});r[field]=list(d.values())
p.write_text(json.dumps(r,indent=2)+'\n');(H/(P+'.md')).write_text(f"# Rust ooutwire audit — in progress\n\n{r['full_source_read_count']}/70 complete source bodies reviewed; {len(r['remaining_work'])} remain. Source-defined finite admission/replay contracts are distinguished from foundational derivation and runtime evidence. GateReceipt unit-test ownership/trait defects are recorded as static findings; no compiler run. Exact source hashes, line ranges and per-file limits are in JSON.\n")
